import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { theme, Typography } from 'antd';
import cn from 'classnames';

import { ITool } from 'entities/Tools';
import { EYmEvents, EYmEventsO1, EYmEventsO2 } from 'shared/typings';
import { ButtonStyleLink } from 'shared/ui';
import { sendYmEvent } from 'shared/utils';

import styles from './ToolsCard.module.scss';

interface ICardProps extends HTMLAttributes<HTMLDivElement> {
	tool: ITool;
}

export const ToolsCard: FC<ICardProps> = ({ className, tool, ...props }) => {
	const { t } = useTranslation();
	const {
		token: { colorBorderSecondary, colorTextSecondary },
	} = theme.useToken();

	return (
		<div {...props} className={cn(className, styles.toolsCard)} style={{ borderColor: colorBorderSecondary }}>
			<Typography.Title level={5} className={styles.toolsCard__title} style={{ color: colorTextSecondary }}>
				<img src={tool.icon} alt={tool.title} />
				{tool.title}
			</Typography.Title>
			<Typography.Paragraph type="secondary">{tool.description}</Typography.Paragraph>
			<ButtonStyleLink
				className={styles.toolsCard__btn}
				to={tool.link}
				onClick={() =>
					sendYmEvent({
						event: EYmEvents.CLICK_INSTRUMENT,
						o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.INSTRUMENTS],
						o2: EYmEventsO2.INSTRUMENTS_LIST,
						o4: tool.name,
					})
				}>
				{t('Подробнее')}
			</ButtonStyleLink>
		</div>
	);
};
