import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import cn from 'classnames';

import { ToolsCard } from 'entities/Tools';
import { toolsList } from 'pages/Tools/consts/toolsList';
import { Page, PageTitle } from 'shared/ui';

import styles from './Tools.module.scss';

interface IToolsProps extends HTMLAttributes<HTMLDivElement> {}

export const Tools: FC<IToolsProps> = ({ className, ...props }) => {
	const { t } = useTranslation();

	return (
		<Page {...props} className={cn(className, styles.tools)}>
			<PageTitle>{t('Мои инструменты')}</PageTitle>
			<div className={styles.tools__wrap}>
				{toolsList.map((tool) => (
					<ToolsCard key={tool.link} tool={tool} />
				))}
			</div>
		</Page>
	);
};

export default Tools;
